const routes:Record<string,string>={Home:'home',Library:'library',Cases:'cases',Historical:'cases/history',Knowledge:'knowledge',Incidents:'incidents',Settings:'connections',References:'guides',Research:'research',Studies:'studies',Story:'story'};
