 useEffect(()=>{const sync=()=>{const id=new URLSearchParams(location.hash.split('?')[1]||'').get('article');setKnowledgeTarget(id);if(id)setKnowledgeSearch('');};window.addEventListener('hashchange',sync);return()=>window.removeEventListener('hashchange',sync);},[]);
 useEffect(()=>{if(view!=='Knowledge')return;if(knowledgeTarget)requestAnimationFrame(()=>document.getElementById('article-'+knowledgeTarget)?.scrollIntoView({block:'start'}));},[view,knowledgeTarget,w?.articles.length]);
 const [replay,setReplay]=useState<Record<string,string>|null>(null);
 const c=w?.cases.find(c=>c.id===selected)||w?.cases[0];
 async function act(path:string,method:string,body:unknown,message:string,after?:(result:any)=>void){const epoch=navigationEpoch.current;setBusy(true);setFailure('');try{const result=await api(path,method,body);await client.invalidateQueries({queryKey:['workspace']});await client.invalidateQueries({queryKey:['reflection']});setNotice(message);if(epoch===navigationEpoch.current){setModal(null);after?.(result);}}catch(e){setFailure((e as Error).message);}finally{setBusy(false);}}
 function open(kind:NonNullable<ModalState>['kind'],article?:Article,incidentId?:string){setReplay(null);setModal({kind,article,incidentId});}
