 if(error||!w)return <main className="fatal"><h1>Lucid could not connect.</h1><p>{String(error||'No workspace is available.')}</p><button onClick={()=>client.invalidateQueries({queryKey:['workspace']})}>Try again</button></main>;
 const cloudBlocked=!!w.config.cloudRequired&&!w.config.cloudMemoryAvailable;
 const useHindsight=w.config.cloudRequired?true:(useHindsightSetting??!!w.config.cloudMemoryAvailable);
 const company=w.companies.find(o=>o.id===c?.companyId);
 const knownCompany=company&&company.kind!=='public-source'&&!/^(Anonymous public|Research replay)/.test(company.name);
