   {view==='Historical'&&<HistoricalCases workspace={w} openCase={selectCase}/>}
   {['Library','References','Research','Studies'].includes(view)&&<div className="library-nav"><button className={view==='Library'?'active':''} onClick={()=>setView('Library')}>Public reports</button><button className={view==='Studies'?'active':''} onClick={()=>setView('Studies')}>Incident studies · {studies.length}</button><button className={view==='References'?'active':''} onClick={()=>setView('References')}>Technical guides</button><details><summary>Advanced</summary><button onClick={()=>setView('Research')}>Replay &amp; evaluation</button></details></div>}
   {view==='Studies'&&<CompanyFieldNotes read={readStudy} query={search} setQuery={setSearch}/>}
